public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends messages from a quick reply shortcut. Requires Telegram Business subscription. Can't be used to send paid messages
    /// </summary>
    public Task<TdLib.TdApi.Objects.Messages> SendQuickReplyShortcutMessagesAsync(long chatId = default, int shortcutId = default, int sendingId = default)
    {

           using var activity =  StartCallActivity("SendQuickReplyShortcutMessagesAsync", typeof(SendQuickReplyShortcutMessages).FullName ?? "SendQuickReplyShortcutMessagesAsync");

           try
           {
             return client.SendQuickReplyShortcutMessagesAsync(chatId, shortcutId, sendingId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
